// Builds the site into the dist folder: the home page and version.json.
// GitHub Actions sets GITHUB_SHA to the commit it is building. On your own computer version.json says dev.
// version.json is public, so it holds only the commit sha. Never write process.env, or anything copied from it, into a file:
// it can hold tokens.
const fs = require("node:fs");
const path = require("node:path");
const { renderHome } = require("../src/site");

const given = process.env.GITHUB_SHA || process.env.GIT_SHA || "";
const sha = /^[0-9a-f]{7,40}$/i.test(given) ? given : "dev";

const out = path.join(__dirname, "..", "dist");
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "index.html"), renderHome());
fs.writeFileSync(path.join(out, "version.json"), JSON.stringify({ sha }) + "\n");
console.log("Built dist/index.html and dist/version.json");
